public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    int len = str.length();
    if (len > lb.getRemaining()) {
        lb = session.getAllocator().allocate(len);
    }
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            lb.append((byte) c);
        } else if (c <= 0x7FF) {
            lb.append((byte) (0xC0 | (c >> 6)));
            lb.append((byte) (0x80 | (c & 0x3F)));
        } else if (Character.isSurrogate(c)) {
            if (i + 1 < len) {
                char high = c;
                char low = str.charAt(++i);
                if (Character.isHighSurrogate(high) && Character.isLowSurrogate(low)) {
                    int codePoint = Character.toCodePoint(high, low);
                    if (codePoint <= 0x10FFFF) {
                        lb.append((byte) (0xF0 | (codePoint >> 18)));
                        lb.append((byte) (0x80 | ((codePoint >> 12) & 0x3F)));
                        lb.append((byte) (0x80 | ((codePoint >> 6) & 0x3F)));
                        lb.append((byte) (0x80 | (codePoint & 0x3F)));
                    }
                }
            }
        } else {
            lb.append((byte) (0xE0 | (c >> 12)));
            lb.append((byte) (0x80 | ((c >> 6) & 0x3F)));
            lb.append((byte) (0x80 | (c & 0x3F)));
        }
    }
    return lb;
}
